import type { Readable } from "node:stream";

/**
 * Where uploaded bytes live. The business logic (uploads, downloads, authorization, the `files` table) only
 * talks to this interface, so moving from the local disk to S3 (or back) never touches a route.
 *
 * Keys are generated by the server as `<organizationId>/<uuid>` and are identical in every backend, so a
 * plain copy of the objects (see scripts/migrate-storage-to-s3.ts) keeps every `files.storage_key` valid.
 */
export interface StorageProvider {
  readonly name: "local" | "s3";
  /** Stores the bytes under a new key (never overwrites on purpose: keys are random UUIDs). */
  put(key: string, body: Buffer, contentType: string): Promise<void>;
  /** Streams the object. Throws StorageNotFoundError when it does not exist. */
  open(key: string): Promise<Readable>;
  /** Size of the object, or null when it does not exist. */
  stat(key: string): Promise<{ size: number } | null>;
  /** Deletes the object; deleting a missing object is not an error. */
  remove(key: string): Promise<void>;
  /** Cheap readiness check (no object is uploaded or downloaded). */
  health(): Promise<boolean>;
}

export class StorageNotFoundError extends Error {
  constructor() {
    super("stored file not found");
    this.name = "StorageNotFoundError";
  }
}

/** `<org uuid>/<file uuid>`: nothing else is ever accepted as a key, so user input can never become a path. */
export const KEY_RE = /^[0-9a-f-]{36}\/[0-9a-f-]{36}$/;

export function assertKey(key: string): void {
  if (!KEY_RE.test(key)) throw new Error("Invalid storage key");
}
